export type PostHogConfig = {
    apiKey: string
    host: string
}

export type TelemetryContext = {
    sdkVersion: string
    // Free-form distribution-channel label set by the consumer. Known values: 'CLI' (now-sdk),
    // 'IDE' (Glider), 'aiux', 'sns'/'ide' (build-agent). Open union keeps
    // autocomplete for the canonical values while accepting any consumer's label.
    clientName: 'CLI' | 'IDE' | (string & {})
    nodeVersion?: string
    os?: string
    ide?: string
    ideVersion?: string
    hostname?: string
    codingAgent?: string
    ciName?: string
    isCI: boolean
    fromConversion?: boolean
}

export type TelemetryProperties = Record<string, unknown>

export type ErrorCategory =
    | 'auth'
    | 'build'
    | 'config'
    | 'download'
    | 'install'
    | 'network'
    | 'transform'
    | 'validation'
    | 'unknown'

export interface Telemetry {
    capture(event: string, properties?: TelemetryProperties): void
    captureError(event: string, error: unknown, properties?: TelemetryProperties): void
    flush(): Promise<void>
    shutdown(): Promise<void>
}

export interface ErrorFingerprint {
    category: ErrorCategory
    fingerprint: string
}
